import gleam/list
import gleam/float
import gleam/result

pub type PhotonicLayer {
  PhotonicLayer(
    mzi_mesh: List(List(MZInterferometer>>,
    wavelength: Float,
    refractive_index: Float,
  )
}

pub type MZInterferometer {
  MZInterferometer(
    theta: Float,
    phi: Float,
    transmission_matrix: List(List(Complex>>,
  )
}

pub type Complex {
  Complex(real: Float, imag: Float)
}

pub type OpticalSignal {
  OpticalSignal(
    amplitude: Float,
    phase: Float,
    wavelength: Float,
  )
}

pub fn create_photonic_layer(size: Int, wavelength: Float) -> PhotonicLayer {
  let mesh = list.map(list.range(0, size - 1), fn(_) {
    list.map(list.range(0, size - 1), fn(_) {
      MZInterferometer(
        theta: 0.0,
        phi: 0.0,
        transmission_matrix: mzi_matrix(0.0, 0.0),
      )
    })
  })

  PhotonicLayer(
    mzi_mesh: mesh,
    wavelength: wavelength,
    refractive_index: 1.45,
  )
}

fn mzi_matrix(theta: Float, phi: Float) -> List(List(Complex>> {
  let cos_theta = float.cos(theta) |> result.unwrap(1.0)
  let sin_theta = float.sin(theta) |> result.unwrap(0.0)
  let exp_phi = Complex(
    real: float.cos(phi) |> result.unwrap(1.0),
    imag: float.sin(phi) |> result.unwrap(0.0),
  )

  [
    [
      Complex(real: cos_theta, imag: 0.0),
      complex_multiply(Complex(real: 0.0, imag: sin_theta), exp_phi),
    ],
    [
      complex_multiply(Complex(real: 0.0, imag: sin_theta), complex_conjugate(exp_phi)),
      Complex(real: cos_theta, imag: 0.0),
    ],
  ]
}

pub fn optical_forward_pass(
  layer: PhotonicLayer,
  input_signals: List(OpticalSignal),
) -> List(OpticalSignal) {
  list.fold(layer.mzi_mesh, input_signals, fn(signals, mzi_row) {
    apply_mzi_row(signals, mzi_row)
  })
}

fn apply_mzi_row(
  signals: List(OpticalSignal),
  mzi_row: List(MZInterferometer),
) -> List(OpticalSignal) {
  list.zip(signals, mzi_row)
  |> list.map(fn(pair) {
    let signal = pair.0
    let mzi = pair.1
    apply_mzi(signal, mzi)
  })
}

fn apply_mzi(signal: OpticalSignal, mzi: MZInterferometer) -> OpticalSignal {
  let input_complex = Complex(
    real: signal.amplitude *. {float.cos(signal.phase) |> result.unwrap(1.0)},
    imag: signal.amplitude *. {float.sin(signal.phase) |> result.unwrap(0.0)},
  )

  let upper = result.unwrap(
    list.at(mzi.transmission_matrix, 0) 
    |> result.then(list.at(_, 0)),
    Complex(1.0, 0.0),
  )

  let output = complex_multiply(input_complex, upper)

  OpticalSignal(
    amplitude: complex_magnitude(output),
    phase: complex_phase(output),
    wavelength: signal.wavelength,
  )
}

fn complex_multiply(a: Complex, b: Complex) -> Complex {
  Complex(
    real: a.real *. b.real -. a.imag *. b.imag,
    imag: a.real *. b.imag +. a.imag *. b.real,
  )
}

fn complex_conjugate(c: Complex) -> Complex {
  Complex(real: c.real, imag: -1.0 *. c.imag)
}

fn complex_magnitude(c: Complex) -> Float {
  float.square_root(c.real *. c.real +. c.imag *. c.imag) |> result.unwrap(0.0)
}

fn complex_phase(c: Complex) -> Float {
  case c.real == 0.0 && c.imag == 0.0 {
    True -> 0.0
    False -> {
      let atan2_result = float.atan(c.imag /. c.real) |> result.unwrap(0.0)
      case c.real <. 0.0 {
        True -> atan2_result +. 3.14159265359
        False -> atan2_result
      }
    }
  }
}

pub fn train_photonic_layer(
  layer: PhotonicLayer,
  input: List(OpticalSignal),
  target: List(OpticalSignal),
  learning_rate: Float,
) -> PhotonicLayer {
  let output = optical_forward_pass(layer, input)
  let gradients = compute_optical_gradients(output, target)

  let updated_mesh = list.index_map(layer.mzi_mesh, fn(row, i) {
    list.index_map(row, fn(mzi, j) {
      let grad_theta = result.unwrap(
        list.at(gradients, i) |> result.then(fn(g) { list.at(g, j) }),
        0.0,
      )

      MZInterferometer(
        theta: mzi.theta -. learning_rate *. grad_theta,
        phi: mzi.phi,
        transmission_matrix: mzi_matrix(
          mzi.theta -. learning_rate *. grad_theta,
          mzi.phi,
        ),
      )
    })
  })

  PhotonicLayer(
    mzi_mesh: updated_mesh,
    wavelength: layer.wavelength,
    refractive_index: layer.refractive_index,
  )
}

fn compute_optical_gradients(
  output: List(OpticalSignal),
  target: List(OpticalSignal),
) -> List(List(Float>> {
  list.zip(output, target)
  |> list.map(fn(pair) {
    let diff = pair.0.amplitude -. pair.1.amplitude
    [diff, diff *. 0.5]
  })
}

pub fn phase_modulation(signal: OpticalSignal, modulation_depth: Float) -> OpticalSignal {
  OpticalSignal(
    amplitude: signal.amplitude,
    phase: signal.phase +. modulation_depth,
    wavelength: signal.wavelength,
  )
}

pub fn wavelength_division_multiplex(
  signals: List(OpticalSignal),
  wavelengths: List(Float),
) -> List(OpticalSignal) {
  list.zip(signals, wavelengths)
  |> list.map(fn(pair) {
    OpticalSignal(
      amplitude: pair.0.amplitude,
      phase: pair.0.phase,
      wavelength: pair.1,
    )
  })
}

